{
  "title": "The Gilded Cage",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party approaches the ruined royal city.",
      "visual_description": "A crumbling stone wall with broken battlements, ivy clinging to old royal banners flapping in the wind, the city gate a twisted wreck of iron.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings at the outer market.",
      "visual_description": "Huddled figures in ragged cloaks, a woman clutching a child, a crier with empty eyes gesturing toward the inner city, smoke rising from a distant tower.",
      "characters": ["Kaelen", "Mira", "Thorne", "Town Elder"]
    },
    {
      "scene_number": 3,
      "caption": "An armored patrol blocks the main gate.",
      "visual_description": "Four soldiers in dented plate armor bearing the old royal crest, spears crossed, one wears a cracked helmet, torchlight glints off their shields.",
      "characters": ["Patrol Captain", "Patrol Guard", "Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 4,
      "caption": "The party sneaks through a forgotten sewer entrance.",
      "visual_description": "Dark, slime-covered tunnel, water dripping from above, faint green glow from a distant grate, spiderwebs thick as rope.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 5,
      "caption": "They emerge in an abandoned courtyard with a cursed tower.",
      "visual_description": "A spiral tower of black stone, windows sealed with iron bars, a single raven perched on a broken spire, dead grass in pale rings around the base.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon draw them to a scorched marketplace.",
      "visual_description": "Charred stalls, overturned carts, a long shadow of a winged creature passes overhead, ashes swirl in the hot air, a child's doll lies melted on the cobbles.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 7,
      "caption": "They find a magic door inscribed with runes.",
      "visual_description": "A massive door of dark wood with living runes that pulse blue, a single eye carved in the center, the frame hums with power.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 8,
      "caption": "Mira deciphers the door's riddle under torchlight.",
      "visual_description": "Her fingers tracing the glowing runes, Kaelen holding a flickering torch, Thorne watching the shadows for patrols, the runes shift as she speaks.",
      "characters": ["Mira", "Kaelen", "Thorne"]
    },
    {
      "scene_number": 9,
      "caption": "The door opens into a grand hall of illusions.",
      "visual_description": "Mirrored walls reflecting infinite copies of the party, floating chandeliers, a throne of gold that shifts to a cage, whispers of lost loved ones.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 10,
      "caption": "They resist temptations and find a hidden staircase.",
      "visual_description": "One mirror shows a feast, another a pile of gems, but Mira spots a faint outline of stairs behind a false panel, Kaelen pushes it open.",
      "characters": ["Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 11,
      "caption": "The staircase leads to a prison cell holding a captive.",
      "visual_description": "A damp, stone room with manacles on the wall, a figure in rags slumped in the corner, a single shaft of light from a high window.",
      "characters": ["Kaelen", "Mira", "Thorne", "Prisoner"]
    },
    {
      "scene_number": 12,
      "caption": "They free the prisoner who is the key to the curse.",
      "visual_description": "The prisoner looks up with pale eyes, a silver key hangs around her neck, Thorne breaks the lock with his axe, chains clatter to the floor.",
      "characters": ["Prisoner", "Kaelen", "Mira", "Thorne"]
    },
    {
      "scene_number": 13,
      "caption": "A magical alarm sounds as they exit the tower.",
      "visual_description": "Red light pulses from the tower's peak, a deep horn blast echoes, armored boots thud in the distance, the sky darkens.",
      "characters": ["Kaelen", "Mira", "Thorne", "Prisoner"]
    },
    {
      "scene_number": 14,
      "caption": "Patrols converge on them from all sides.",
      "visual_description": "Soldiers pour from side streets, shields locked, spears lowered, a commander shouts orders, the party is cornered against a wall.",
      "characters": ["Patrol Captain", "Patrol Guard", "Kaelen", "Mira", "Thorne", "Prisoner"]
    },
    {
      "scene_number": 15,
      "caption": "Thorne holds the line while the others flee.",
      "visual_description": "Thorne plants his feet, swinging a heavy axe, sparks fly from clashing steel, he roars as he pushes back the first wave, blood on his arm.",
      "characters": ["Thorne", "Patrol Guard", "Kaelen", "Mira", "Prisoner"]
    },
    {
      "scene_number": 16,
      "caption": "They race through the city toward the escape bridge.",
      "visual_description": "Blur of ruined buildings, torn banners, a fountain of dried blood, Mira drags the prisoner, Kaelen covers their rear with arrows, the bridge looms ahead.",
      "characters": ["Kaelen", "Mira", "Prisoner"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge is partially collapsed but crossable.",
      "visual_description": "A stone arch missing half its span, ropes hanging from broken pillars, a deep chasm below with mist rising, a single plank wobbles over the gap.",
      "characters": ["Kaelen", "Mira", "Prisoner", "Thorne"]
    },
    {
      "scene_number": 18,
      "caption": "They cross and collapse the bridge behind them.",
      "visual_description": "Kaelen cuts the last rope, the bridge groans and falls into the chasm, the party stands panting on the far side, the ruined city now cut off, dawn breaks.",
      "characters": ["Kaelen", "Mira", "Thorne", "Prisoner"]
    }
  ]
}

